    const gear=slots.map(([slot,icon,name])=>{const id=p.equip.find(id=>CARD_MAP[CARD_BY_ID[id].kind].slot===slot),abolished=p.skillState?.abolished.includes(slot);return id?`<span class="gear-container"><button class="gear-slot occupied" data-card="${id}" data-zone="equip" data-owner="${esc(p.id)}" data-face="${CARD_BY_ID[id].kind}" data-face-id="${id}" title="${name}：${CARD_MAP[CARD_BY_ID[id].kind].name}" aria-label="${esc(p.name)} ${name} ${CARD_MAP[CARD_BY_ID[id].kind].name}">${icon}</button><button class="gear-info" data-ui="card-info" data-kind="${CARD_BY_ID[id].kind}" data-id="${id}" aria-label="${name}效果详情">ⓘ</button></span>`:`<span class="gear-slot ${abolished?'abolished':''}" title="${abolished?'已废除':'空'}${name}" aria-label="${abolished?'已废除':'空'}${name}">${icon}</span>`;}).join('');
