    for(let pass=0;pass<n;pass++){let changed=false;for(let i=0;i<points.length;i++)for(let j=i+1;j<points.length;j++){const a=points[i],b=points[j];if(Math.abs(a.x-b.x)<a.hw+b.hw+3&&Math.abs(a.y-b.y)<a.hh+b.hh+3){for(const p of [a,b])if(p.x!==p.baseX||p.y!==p.baseY){p.x=p.baseX;p.y=p.baseY;changed=true;}}}if(!changed)break;}
    const perspective=`${v.roomId}:${v.you}`;if(this.seatPerspective!==perspective){this.seatPoints=new Map();this.seatPerspective=perspective;}
    this.seatPoints??=new Map();
