      if(prev&&prev.room===v.roomId&&prev.w===w&&prev.h===h&&!this.reduceMotion&&(prev.x!==x||prev.y!==y))el.animate([{left:prev.x+'px',top:prev.y+'px'},{left:x+'px',top:y+'px'}],{duration:400,easing:'ease-in-out'});
      this.seatPoints.set(p.id,dest);el.classList.toggle('side-start',sx<50);el.classList.toggle('side-end',sx>50);el.classList.toggle('side-middle',sx===50);el.classList.add(p.id===v.you?'lane-self':sy<25?'lane-top':sx<50?'lane-left':'lane-right');
